-- 0010: privacy hardening (PHASE-2C §2c.2-B, §2c.2-C).
--   1. pins.society_key: the society name normalised for grouping (lower-case, punctuation to
--      spaces, the words apartment(s)/residency/enclave removed, spaces collapsed). Generated by
--      the database, never public.
--   2. public_pins (k-anonymity): society_name is shown ONLY when at least 3 active, non-outlier
--      pins with the same society_key lie within 300 m of the pin; otherwise it is NULL.
--      sqft is never exact any more: the column stays (same type, so `create or replace` keeps the
--      view and its grants) but is always NULL, and a new LAST column sqft_band gives the bucket
--      (lt500, 500_800, 800_1200, 1200_plus). The base table keeps the exact value.
--   3. consented_at on pins, reports, tolet_boards and tolet_reports: when the person ticked the
--      consent box (set by the Edge Functions). NULL for rows from before this migration.
-- Grants are unchanged. The view keeps owner rights + security_barrier as in 0001-0004, and calls
-- no new function (anon would need EXECUTE on any function a view calls).
-- The 300 m test is plain arithmetic on st_x/st_y, not st_dwithin/st_distance on geography: those
-- look up the spheroid with an internal query on extensions.spatial_ref_sys that runs as the
-- CALLING role (anon), which has no access to it (tests/db/run.sh would fail with "permission
-- denied for schema extensions"). Granting anon that access would loosen grants, so we don't.
-- The society_key index narrows the candidates to a handful of rows first; no spatial index needed.

-- 1. ----------------------------------------------------------------------------------------------
alter table public.pins
  add column if not exists society_key text generated always as (
    nullif(btrim(regexp_replace(
      regexp_replace(
        regexp_replace(lower(society_name), '[^[:alnum:]]+', ' ', 'g'),
        '\m(apartment|apartments|residency|enclave)\M', ' ', 'g'),
      '\s+', ' ', 'g')), '')
  ) stored;

create index if not exists pins_society_key_idx on public.pins (society_key)
  where society_key is not null and status = 'active' and not is_outlier;

-- 2. ----------------------------------------------------------------------------------------------
-- Same columns, same order as 0004_tolet_and_survey.sql; sqft and society_name change only their
-- expression (same types), sqft_band is appended at the END.
create or replace view public.public_pins with (security_barrier) as
select
  id, kind, property_type, bhk, rent, furnishing, gated, maintenance_incl,
  deposit_months,
  null::integer as sqft,
  parking_cars,
  case
    when p.society_key is not null and (
      select count(*)
      from public.pins q
      where q.society_key = p.society_key
        and q.status = 'active' and not q.is_outlier and q.report_count < 3
        and (q.listing_expires_at is null or q.listing_expires_at > now())
        -- metres, flat-earth approximation (well under 0.5% off at 300 m; pins are rounded to ~110 m)
        and 111320 * sqrt(
              power(extensions.st_y(q.location::extensions.geometry)
                    - extensions.st_y(p.location::extensions.geometry), 2)
            + power((extensions.st_x(q.location::extensions.geometry)
                     - extensions.st_x(p.location::extensions.geometry))
                    * cos(radians(extensions.st_y(p.location::extensions.geometry))), 2)
          ) <= 300
    ) >= 3 then p.society_name
  end as society_name,
  occupants, pets_allowed,
  waterlogging, water_supply, power_backup, pg_meals, pg_gender,
  available_from, tenant_pref, room_gender_pref, room_smoking_ok, room_food_pref,
  one_liner, locality_slug, is_outlier, created_at,
  extensions.st_y(location::extensions.geometry) as lat,
  extensions.st_x(location::extensions.geometry) as lng,
  water_sources, water_availability, water_litres, water_hours, water_extra_cost,
  water_shared, drinking_water, water_note,
  waterlog_where, waterlog_severity, waterlog_duration, road_in_rain, floor_level, waterlog_note,
  power_cuts, maintenance_amount, conditions_as_of,
  source, location_approx,
  case
    when p.sqft is null then null
    when p.sqft < 500 then 'lt500'
    when p.sqft < 800 then '500_800'
    when p.sqft < 1200 then '800_1200'
    else '1200_plus'
  end as sqft_band
from public.pins p
where status = 'active'
  and report_count < 3
  and (listing_expires_at is null or listing_expires_at > now());

-- 3. ----------------------------------------------------------------------------------------------
alter table public.pins          add column if not exists consented_at timestamptz;
alter table public.reports       add column if not exists consented_at timestamptz;
alter table public.tolet_boards  add column if not exists consented_at timestamptz;
alter table public.tolet_reports add column if not exists consented_at timestamptz;
